package in.jharkhand.civic.repository;
import in.jharkhand.civic.port.*;import org.springframework.stereotype.Component;import java.util.*;
@Component class JsonProblemRepository implements ProblemRepository{private final JsonStore s;JsonProblemRepository(JsonStore s){this.s=s;}public List<Map<String,Object>> findAll(){return s.read("problems.json");}public Optional<Map<String,Object>> findById(String id){return Optional.ofNullable(s.find("problems.json",id));}}
@Component class JsonDepartmentRepository implements DepartmentRepository{private final JsonStore s;JsonDepartmentRepository(JsonStore s){this.s=s;}public List<Map<String,Object>> findAll(){return s.read("departments.json");}public Optional<Map<String,Object>> findById(String id){return Optional.ofNullable(s.find("departments.json",id));}}
@Component class JsonInstitutionRepository implements InstitutionRepository{private final ReferenceServiceHolder h;JsonInstitutionRepository(ReferenceServiceHolder h){this.h=h;}public List<Map<String,Object>> findAll(){return h.all();}public Optional<Map<String,Object>> findById(String id){return h.all().stream().filter(x->id.equals(String.valueOf(x.get("id")))).findFirst();}}
@Component class JsonProjectRepository implements ProjectRepository{private final JsonStore s;JsonProjectRepository(JsonStore s){this.s=s;}public List<Map<String,Object>> findAll(){return s.read("projects.json");}public Optional<Map<String,Object>> findById(String id){return Optional.ofNullable(s.find("projects.json",id));}}
@Component class ReferenceServiceHolder{private final JsonStore s;ReferenceServiceHolder(JsonStore s){this.s=s;}List<Map<String,Object>> all(){List<Map<String,Object>>x=new ArrayList<>();for(int i=1;i<=4;i++)x.addAll(s.read("institutions-tier"+i+".json"));return x;}}
